-- Kadir Coaching database schema
-- Import this file with phpMyAdmin or the MySQL command-line client.

CREATE DATABASE IF NOT EXISTS kadir_coaching
  CHARACTER SET utf8mb4 COLLATE utf8mb4_turkish_ci;
USE kadir_coaching;

CREATE TABLE IF NOT EXISTS posts (
  ID INT UNSIGNED NOT NULL AUTO_INCREMENT,
  title VARCHAR(255) NOT NULL,
  summary TEXT NOT NULL,
  content MEDIUMTEXT NOT NULL,
  category TINYINT UNSIGNED NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  view_count INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (ID),
  KEY idx_posts_category (category),
  KEY idx_posts_views_date (view_count, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

CREATE TABLE IF NOT EXISTS users (
  ID INT UNSIGNED NOT NULL AUTO_INCREMENT,
  USERNAME VARCHAR(100) NOT NULL,
  MAIL VARCHAR(190) NOT NULL,
  PASSWORD VARCHAR(255) NOT NULL COMMENT 'Stores password_hash() output, never plaintext passwords',
  user_role ENUM('admin', 'user') NOT NULL DEFAULT 'user',
  PRIMARY KEY (ID),
  UNIQUE KEY uq_users_mail (MAIL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

-- Optional sample blog posts from the original student project. No account or password records are included.
