INSERT INTO `posts` (`ID`, `title`, `summary`, `content`, `category`, `created_at`, `view_count`) VALUES
(13, 'Makro Besinler Rehberi: Protein, Karbonhidrat ve Yağ', 'Beslenmenin temeli olan makroları ve vücudumuzdaki görevlerini öğrenin.', '<p>Vücut geliştirmede başarı %70 beslenmedir. Peki yediğimiz besinler ne işe yarıyor?</p><ul><li><strong>Protein (1g = 4 Kalori):</strong> Kasların yapı taşıdır. Onarım ve büyüme için şarttır. (Et, yumurta, balık)</li><li><strong>Karbonhidrat (1g = 4 Kalori):</strong> Vücudun birincil enerji kaynağıdır. Antrenman performansını belirler. (Pirinç, yulaf, patates)</li><li><strong>Yağ (1g = 9 Kalori):</strong> Hormon üretimi ve beyin sağlığı için gereklidir. (Zeytinyağı, kuruyemiş, avokado)</li></ul><p>İyi bir fizik için hiçbirini hayatınızdan tamamen çıkarmamalısınız.</p>', '2', '2025-07-20 21:52:48', 420),
(3, '5x5 Güç Antrenmanı: Temel Kuvvet İnşası', 'Güç kazanmak ve kas kütlesini artırmak isteyenler için efsanevi 5x5 sisteminin detayları.', '<p>Eğer amacınız saf güç kazanmaksa, 5x5 sistemi dünyadaki en popüler ve etkili programlardan biridir. Temel mantık basittir: 5 set ve 5 tekrar ağır kilo.</p><h4>Programın Temelleri</h4><ul><li><strong>Squat:</strong> 5x5</li><li><strong>Bench Press:</strong> 5x5</li><li><strong>Barbell Row:</strong> 5x5</li></ul><p>Bu hareketleri haftada 3 gün, araya birer gün dinlenme koyarak uygulayın. Ağırlıkları her antrenmanda 2.5 kg artırmayı hedefleyin.</p>', '1', '2025-06-26 14:09:58', 451),
(4, 'Evde Ekipmansız Tüm Vücut Antrenmanı', 'Spor salonuna gidemeyenler için sadece vücut ağırlığıyla yapabileceğiniz etkili bir program.', '<p>Spor salonu yok, bahane yok! Kendi vücut ağırlığınızla yapacağınız bu antrenman, metabolizmanızı hızlandıracak.</p><h4>Döngüsel Antrenman (3 Tur)</h4><ol><li>Push Up (Şınav) - 15 Tekrar</li><li>Bodyweight Squat - 20 Tekrar</li><li>Lunge (Her bacak) - 12 Tekrar</li><li>Plank - 45 Saniye</li></ol><p>Hareketler arası dinlenme yok, tur bitiminde 2 dakika dinlenin.</p>', '1', '2025-11-20 14:51:47', 312),
(5, 'Devasa Kollar İçin Süper Set Programı', 'Biceps ve Triceps kaslarını aynı anda çalıştırarak maksimum pompayı yakalayın.', '<p>Kollarınızın büyümediğinden şikayetçiyseniz, antagonist (zıt) kas gruplarını hiç dinlenmeden arka arkaya çalıştırmayı deneyin.</p><h4>Örnek Süper Set</h4><p><strong>1. Set:</strong> Barbell Curl (10 Tekrar) + Lying Triceps Extension (12 Tekrar)<br><strong>2. Set:</strong> Hammer Curl (12 Tekrar) + Triceps Pushdown (15 Tekrar)</p><p>Setler arasında 60 saniye dinlenin ve kan akışını hissedin.</p>', '1', '2025-09-27 00:58:29', 589),
(6, '3 Boyutlu Omuzlar İçin Antrenman Rehberi', 'Omuz başlarını her açıdan vurarak daha geniş ve estetik bir görünüm elde edin.', '<p>Geniş omuzlar estetik bir fiziğin anahtarıdır. Omuz kası üç parçadan oluşur: Ön, Yan ve Arka. Hepsini vurmalısınız.</p><ul><li><strong>Overhead Press:</strong> Genel kütle için temel hareket.</li><li><strong>Lateral Raise:</strong> Yan omuzları izole ederek genişlik katar.</li><li><strong>Face Pull:</strong> Arka omuz ve postür sağlığı için vazgeçilmezdir.</li></ul>', '1', '2025-09-25 17:29:34', 276),
(7, 'Bacak Gününü Atlamayın: Tavuk Bacaklara Son', 'Vücudun en büyük kas grubunu çalıştırmak testosteron seviyenizi artırır.', '<p>Bacak antrenmanı sadece bacaklarınızı değil, tüm vücudun anabolik hormon üretimini tetikler. İşte olmazsa olmazlar:</p><h4>Hareketler</h4><table class=\"table table-bordered\"><tr><td>Squat</td><td>4 Set x 8 Tekrar</td></tr><tr><td>Leg Press</td><td>4 Set x 12 Tekrar</td></tr><tr><td>Romanian Deadlift</td><td>3 Set x 10 Tekrar</td></tr><tr><td>Calf Raise</td><td>4 Set x 20 Tekrar</td></tr></table>', '1', '2025-12-22 02:26:25', 199),
(8, 'Mükemmel Karın Kasları (Six Pack) Antrenmanı', 'Karın kaslarını belirginleştirmek için yapmanız gereken en iyi izole hareketler.', '<p>Karın kasları mutfakta yapılır ama spor salonunda şekillendirilir. Klasik mekik yerine bu hareketleri deneyin:</p><ul><li><strong>Hanging Leg Raise:</strong> Alt karın için en etkilisi.</li><li><strong>Cable Crunch:</strong> Ağırlıkla yapılan mekik, kasları büyütür.</li><li><strong>Russian Twist:</strong> Yan karın (oblik) kasları için.</li></ul><p>Haftada 2-3 kez antrenman sonuna ekleyebilirsiniz.</p>', '1', '2025-09-01 21:46:54', 661),
(9, 'HIIT Kardiyo ile Yağ Yakımını Hızlandırın', 'Kısa sürede maksimum kalori yakmak için Yüksek Yoğunluklu Aralıklı Antrenman.', '<p>Saatlerce koşu bandında yürümekten sıkıldınız mı? 15 dakikalık HIIT, 1 saatlik yürüyüşe bedel olabilir.</p><h4>Örnek HIIT Planı</h4><ul><li>30 Saniye: %90 Eforla Sprint (Depar)</li><li>30 Saniye: Hafif Tempo Yürüyüş</li><li>Bunu toplam 10-15 dakika boyunca tekrarlayın.</li></ul><p>Antrenman sonrası \"Afterburn\" etkisiyle yağ yakımı devam eder.</p>', '1', '2025-08-10 20:57:47', 421),
(10, 'Sırtı Genişletmek İçin En İyi Çekiş Hareketleri', 'Üçgen vücut görünümü için latissimus dorsi kaslarını hedefleyin.', '<p>Geniş bir sırt, belinizi daha ince gösterir. Çekiş hareketlerinde dirseklerinizi vücudunuza çekmeye odaklanın.</p><h4>Program</h4><ol><li><strong>Wide Grip Pull Up:</strong> Sırt genişliği kralı.</li><li><strong>Bent Over Barbell Row:</strong> Sırt kalınlığı için.</li><li><strong>Lat Pulldown:</strong> Kontrollü negatif tekrarlar yapın.</li><li><strong>Seated Cable Row:</strong> Kürek kemiklerini birbirine sıkıştırın.</li></ol>', '1', '2025-09-15 23:26:46', 335),
(11, 'Arnold Göğüs Antrenmanı: Üst Göğüs Odaklı', 'Daha dolu ve estetik bir göğüs kafesi için üst göğsü ihmal etmeyin.', '<p>Çoğu kişi sadece Bench Press yapar ama estetik görünümü veren üst göğüstür (Clavicular Head).</p><p>Antrenmana <strong>Incline Dumbbell Press</strong> ile başlayın. Enerjiniz yüksekken zayıf bölgeyi çalışmak gelişimi hızlandırır. Ardından <strong>Cable Crossover</strong> ile göğüs kaslarını esnetip sıkıştırarak bitiriş yapın.</p>', '1', '2025-09-01 06:12:57', 513),
(12, 'Yeni Başlayanlar İçin İlk 1 Ay Programı', 'Fitnessa yeni başlayanlar için adaptasyon süreci ve temel hareketler.', '<p>Sporda yeniyseniz acele etmeyin. İlk ay amacınız hareketlerin formunu öğrenmek ve kas-sinir koordinasyonunu geliştirmektir.</p><h4>Full Body (Tüm Vücut)</h4><p>Haftada 3 gün tüm vücudu çalıştırın. Her bölge için tek bir temel hareket seçin ve 3 set x 12 tekrar yapın. Makineleri kullanmak başlangıç için daha güvenli olabilir.</p>', '1', '2025-07-02 16:56:04', 923),
(14, 'Bölgesel Zayıflama Yalanı: Sadece Göbek Erir Mi?', 'Binlerce mekik çekerek göbek yağlarınızdan kurtulabilir misiniz? Bilim ne diyor?', '<p>Spor salonlarında en sık duyduğumuz efsane: \"Sadece göbeğim gitsin ama bacaklarım kalınlaşmasın.\" Maalesef insan biyolojisi böyle çalışmaz.</p><h4>Gerçek Nedir?</h4><p>Yağ yakımı sistemik bir süreçtir. Kalori açığı oluşturduğunuzda vücut genetik olarak belirlediği bölgelerden yağ yakmaya başlar. Sadece mekik çekmek karın kaslarını güçlendirir ama üzerindeki yağ tabakasını bölgesel olarak yakmaz. Çözüm: Kalori açığı ve sabır.</p>', '2', '2025-08-19 16:19:44', 689),
(15, 'Protein Tozu (Whey) Şart Mı? Zararlı Mı?', 'Supplement dünyasının en popüler ürünü hakkında gerçekler ve kullanım tavsiyeleri.', '<p>Yeni başlayanların ilk sorduğu soru: \"Toz kullanmazsam gelişemez miyim?\"</p><p><strong>Cevap: Hayır, şart değil.</strong> Protein tozu, adı üstünde bir \"takviyedir\". Günlük protein ihtiyacınızı tavuk, yumurta ve etten karşılayabiliyorsanız toza ihtiyacınız yoktur. Ancak pratiklik açısından antrenman sonrası hızlı emilim için whey protein mükemmel bir araçtır. Böbrek sorunu olmayan sağlıklı bireyler için güvenlidir.</p>', '2', '2025-09-02 03:54:46', 515),
(16, 'Uyku ve Kas Gelişimi: Büyüme Uykuda Gerçekleşir', 'Salonda kasları yıkarız, mutfakta besleriz, uykuda ise büyütürüz. İşte uykunun önemi.', '<p>Günde 2 saat antrenman yapıp, beslenmenize dikkat etseniz bile; eğer günde 5-6 saatten az uyuyorsanız gelişiminiz duracaktır.</p><h4>Uykuda Neler Olur?</h4><ul><li><strong>Büyüme Hormonu (GH):</strong> En yoğun salgılandığı zaman derin uykudur.</li><li><strong>Merkezi Sinir Sistemi:</strong> Ağır antrenmanlardan sonra sinir sisteminin toparlanması uykuyla olur.</li><li><strong>Kortizol (Stres):</strong> Uykusuzluk kortizolu artırır, bu da kas yıkımına neden olur.</li></ul>', '2', '2025-10-01 12:20:44', 380),
(17, 'Antrenman Öncesi ve Sonrası Beslenme Stratejileri', 'Performansınızı artırmak ve toparlanmayı hızlandırmak için ne zaman ne yemelisiniz?', '<p><strong>Antrenman Öncesi (2 saat önce):</strong> Kompleks karbonhidrat (Yulaf, Bulgur) ve orta seviye protein. Enerji depolarını doldurmak için.</p><p><strong>Antrenman Sonrası (İlk 30-60 dk):</strong> Hızlı sindirilen protein (Whey veya Yumurta) ve basit karbonhidrat (Muz veya Pirinç Patlağı). Yıpranan kasları onarmak ve glikojen depolarını doldurmak için kritiktir.</p>', '2', '2025-11-21 21:38:49', 490),
(18, 'Kilo Vermek ve Yağ Yakmak Arasındaki Fark', 'Tartıdaki rakamın düşmesi her zaman iyiye işaret değildir. Kas kaybetmediğinize emin olun.', '<p>Hızlı kilo verdiren şok diyetler genellikle su ve kas kaybına neden olur. Bu da metabolizmanızı yavaşlatır ve \"Skinny Fat\" (Zayıf ama yağlı) bir görünüme yol açar.</p><h4>Sağlıklı Olan Nedir?</h4><p>Amacımız tartıda hafiflemek değil, ayna karşısında sıkılaşmak olmalıdır. Haftada 0.5kg - 1kg arası kayıp idealdir. Ağırlık antrenmanı yaparak kas kütlenizi korumalı, sadece yağ dokusunu hedeflemelisiniz.</p>', '2', '2025-12-02 00:48:39', 560),
(19, 'Su Tüketimi ve Performans İlişkisi', 'Dehidrasyon (susuzluk) gücünüzü %20 oranında düşürebilir. Günde ne kadar içmelisiniz?', '<p>Kaslarımızın %75 i sudur. Yeterli su içmemek, kasların düz görünmesine, kramplara ve güç kaybına neden olur.</p><p><strong>Ne kadar içmeli?</strong><br>Ortalama bir sporcu için günde en az 3-4 litre su şarttır. Antrenman esnasında kaybettiğiniz suyu yerine koymak için set aralarında yudum yudum su içmeyi ihmal etmeyin.</p>', '2', '2025-09-01 02:05:57', 290),
(20, 'Cheat Meal (Ödül Öğünü) Nasıl Yapılmalı?', 'Diyeti bozmadan ödül öğünü yapmanın psikolojik ve fizyolojik faydaları.', '<p>Sürekli diyette olmak metabolizmayı yavaşlatabilir ve leptin hormonunu düşürebilir. Haftada bir kez yapılan planlı bir \"Cheat Meal\":</p><ul><li>Metabolizmayı şaşırtır ve hızlandırır.</li><li>Psikolojik olarak rahatlama sağlar ve diyete sadakati artırır.</li><li>Glikojen depolarını doldurur.</li></ul><p><strong>Dikkat:</strong> Tüm gün tıka basa yemek (Cheat Day) değil, sadece tek bir öğünde istediğinizi yemek (Cheat Meal) doğrudur.</p>', '2', '2025-07-26 22:06:17', 714),
(21, 'Progressive Overload (Aşamalı Yükleme) Prensibi', 'Kas büyütmenin tek ve değişmez kuralı nedir? Neden sürekli aynı ağırlıkla çalışmamalısınız?', '<p>Vücut bir adaptasyon makinesidir. 10kg ile 3 set yapmaya alıştığında artık kas geliştirme ihtiyacı duymaz.</p><h4>Gelişim İçin Ne Yapmalı?</h4><p>Her antrenmanda veya her hafta bir şeyi zorlaştırmalısınız:</p><ul><li>Ağırlığı artırmak (+2.5kg)</li><li>Tekrar sayısını artırmak</li><li>Dinlenme süresini kısaltmak</li><li>Formu düzeltmek</li></ul><p>Buna \"Progressive Overload\" denir ve gelişimin anahtarıdır.</p>', '2', '2025-12-12 06:10:06', 445),
(22, 'Metabolizma Hızı Nasıl Artırılır?', 'Oturduğunuz yerde daha fazla kalori yakmak ister misiniz? İşte bilimsel yöntemler.', '<p>Bazı insanlar \"su içse yarıyor\", bazıları ise \"ne yese kilo almıyor\". Bu genetik mi? Kısmen evet, ama değiştirebilirsiniz.</p><h4>Metabolizmayı Hızlandırmanın Yolları</h4><ol><li><strong>Kas Kütlesini Artırmak:</strong> Kas dokusu, yağ dokusundan çok daha fazla kalori harcar.</li><li><strong>NEAT (Günlük Aktivite):</strong> Asansör yerine merdiven kullanmak, yürümek günlük harcamayı artırır.</li><li><strong>Protein Ağırlıklı Beslenmek:</strong> Proteinin sindirilmesi için vücut daha fazla enerji harcar (Termik Etki).</li></ol>', '2', '2025-08-24 04:13:06', 330),
(23, '12 Haftalık Değişim Paketi (En Çok Tercih Edilen)', 'Hayatınızı değiştirmek için 3 ay yeter. Hem antrenman hem beslenme dahil tam kapsamlı sistem.', '<p>Bu paket, \"Nereden başlayacağımı bilmiyorum\" diyenler için en ideal çözümdür. 12 hafta boyunca vücudunuzun nasıl değiştiğine inanamayacaksınız.</p><h4>Paket İçeriği</h4><ul><li><strong>Kişiye Özel Antrenman:</strong> Salon veya ev ortamına uygun.</li><li><strong>Makro Beslenme Planı:</strong> Kalori hesabı yapmanıza gerek kalmadan, sizin için hesaplanmış listeler.</li><li><strong>Haftalık Revize:</strong> Gelişiminize göre program sürekli güncellenir.</li></ul><p>Hedef: Minimum %5-8 yağ kaybı veya kas kütlesi artışı.</p>', '3', '2025-11-10 14:02:12', 858),
(24, 'Hızlı Yağ Yakımı (Definasyon) Paketi', 'Yaza hazırlanmak veya göbek bölgesinden kurtulmak isteyenler için agresif yağ yakım protokolü.', '<p>Sadece tartıda eksilmek değil, hatlarınızı belirginleştirmek istiyorsanız bu paket sizin için.</p><h4>Neler Var?</h4><ul><li>Metabolizma hızlandırıcı özel kardiyo rutinleri.</li><li>İnsülin hassasiyetini artıran beslenme stratejileri (Carb Cycling vb.).</li><li>Yağ yakımını destekleyen supplement kombinasyonları.</li></ul><p>Not: Bu program disiplin gerektirir, kaçamaklara yer yoktur.</p>', '3', '2025-09-27 03:08:25', 623),
(25, 'Clean Bulk (Kas İnşası) Paketi', 'Yağlanmadan büyümek isteyenler için özel makro planlaması ve güç odaklı antrenmanlar.', '<p>Zayıfsınız ve kilo almak istiyorsunuz ya da hacim kazanmak istiyorsunuz ama göbek yapmak istemiyorsunuz. Çözüm: Clean Bulk.</p><h4>Stratejimiz</h4><ul><li>Kas kütlesini artıracak hipertrofi antrenmanları.</li><li>Hacim kazanmanızı sağlayacak yüksek karbonhidratlı beslenme planı.</li><li>Güç artışını takip eden ilerlemeli yükleme sistemi.</li></ul>', '3', '2025-12-17 18:17:41', 540),
(26, 'Öğrenci Dostu Ekonomik Paket', 'Bütçesi kısıtlı öğrenciler için en temel ve etkili programlama. Mazeretleri kaldırıyoruz.', '<p>Spor yapmak lüks değildir. Öğrenci kardeşlerim için kâr amacı gütmeden hazırladığım bu paket, temel doğruları öğrenmenizi sağlar.</p><ul><li>Aylık Antrenman Programı (Tek seferlik planlama).</li><li>Öğrenci bütçesine uygun (Tavuk-Pilav-Yumurta odaklı) beslenme tüyoları.</li><li>Ayda 1 kez form kontrolü.</li></ul><p>Fiyat/Performans odaklı gelişim.</p>', '3', '2025-11-12 22:11:12', 1022),
(38, 'Glute Bridge ve Hip Thrust: Kalça Şekillendirme', 'Sadece kadınlar için değil, güçlü bir alt vücut isteyen herkes için en iyi kalça hareketleri.', '<p>Güçlü kalça kasları, sadece estetik değil, aynı zamanda bel sağlığı ve patlayıcı güç için de kritiktir. Squat kral olabilir ama Hip Thrust kalça gelişiminin kraliçesidir.</p>', '1', '2025-07-15 20:04:52', 174),
(36, 'Mobilite ve Esneklik Rutini: Antrenman Öncesi Isınma', 'Sakatlanmadan daha derin squat yapmak ve daha rahat hareket etmek için 5 dakikalık rutin.', '<p>Soğuk kasla antrenmana başlamak sakatlığa davetiye çıkarmaktır. Dinamik esneme hareketleriyle eklem hareket açıklığınızı (ROM) artırın ve performansınızı ikiye katlayın.</p>', '1', '2025-11-12 20:04:52', 530),
(37, 'Bench Press Ağırlık Artırmanın Yolları (Plateau Kırma)', 'Ağırlıklarınız takıldı mı? Bench press rekorunuzu kırmak için bu taktikleri uygulayın.', '<p>Sürekli aynı ağırlıkla çalışarak gelişemezsiniz. Pause Press (beklemeli kaldırış) yaparak ve triceps kaslarınızı güçlendirerek o takıldığınız noktayı (sticking point) aşabilirsiniz.</p>', '1', '2025-08-28 20:04:52', 279),
(29, 'Sadece Beslenme & Diyet Danışmanlığı', 'Antrenman programım var ama ne yiyeceğimi bilmiyorum diyenler için.', '<p>Vücut mutfakta yapılır. Antrenmanınız ne kadar iyi olursa olsun, beslenmeniz kötüyse sonuç alamazsınız.</p><ul><li>Yaşam tarzınıza uygun (okul/iş saatlerine göre) beslenme planı.</li><li>Alternatifli öğünler (Sıkıldığınızda değiştirebilirsiniz).</li><li>Supplement planlaması.</li><li>Haftalık tartı ve ölçüm takibi.</li></ul>', '3', '2025-07-20 05:18:04', 331),
(35, 'Kettlebell Swing ile Yağ Yakımı ve Güç', 'Tek bir ekipmanla tüm vücudu çalıştırın ve nabzınızı tavan yaptırın.', '<p>Kettlebell Swing, hem arka zincir (posterior chain) kaslarını güçlendirir hem de inanılmaz bir kardiyo etkisi yaratır. 15 dakikalık bir swing antrenmanı, 45 dakikalık koşuya bedel olabilir.</p>', '1', '2025-07-22 20:04:52', 115),
(31, 'Yarışma Hazırlık Paketi (Comp Prep)', 'Podyuma çıkmak veya fotoğraf çekimi için %5 yağ oranına inmek isteyen ileri seviye sporculara.', '<p>Bu paket sadece ileri seviye sporcular içindir. İrade, sabır ve limitleri zorlamayı gerektirir.</p><ul><li>Yarışma takvimine göre Peak Week (Zirve Haftası) planlaması.</li><li>Su atımı ve yükleme stratejileri.</li><li>Posing (Poz verme) dersleri.</li><li>Detaylı supplement ve kür planlaması (Gerekiyorsa).</li></ul>', '3', '2025-10-05 10:53:32', 151),
(33, 'Deadlift Teknik Rehberi: Bel Sakatlıklarından Korunun', 'Deadlift kralların hareketidir ama yanlış yapılırsa sakatlar. Adım adım doğru form rehberi.', '<p>Deadlift yaparken beliniz ağrıyorsa bir şeyler yanlış demektir. Barı kaval kemiğine yapışık tutmalı, kalçayı geriye vermeli ve omurgayı nötr pozisyonda kilitlemelisiniz. Ego lifting yapmayın, formunuzu düzeltin.</p>', '1', '2025-05-16 20:04:52', 168),
(34, 'Calisthenics Başlangıç: Vücut Ağırlığıyla Kas Yapın', 'Spor salonuna gitmeden, sadece parkta veya evde vücut ağırlığıyla estetik bir fizik inşa edin.', '<p>Barfiks, şınav ve dips... Bu üçlü, antik çağlardan beri en atletik vücutların sırrıdır. Kendi vücut ağırlığınızı kontrol etmeyi öğrendiğinizde, ağırlık kaldırmanın çok daha kolay olduğunu göreceksiniz.</p>', '1', '2025-04-28 20:04:52', 610),
(39, 'Omuz Sakatlıklarını Önlemek İçin Rotator Cuff Egzersizleri', 'Omuzlarınız kütürdüyor mu? Rotator manşet kaslarını güçlendirerek omuz sağlığınızı koruyun.', '<p>Omuz eklemi vücudun en hareketli ama en narin eklemidir. Face Pull ve External Rotation hareketlerini her itiş antrenmanının sonuna eklemeyi ihmal etmeyin.</p>', '1', '2025-10-06 20:04:52', 439),
(40, 'Drop Set ve Süper Set Farkı Nedir?', 'Antrenman yoğunluğunu artırmak için kullanılan bu iki teknik arasındaki farkı öğrenin.', '<p>Süper Set, iki hareketi dinlenmeden yapmaktır. Drop Set ise tükenişe gittikten sonra ağırlığı azaltıp devam etmektir. İkisi de şok etkisi yaratır ama her antrenmanda kullanılmamalıdır.</p>', '1', '2025-11-16 20:04:52', 415),
(41, 'Bilek Güreşi ve Ön Kol (Forearm) Geliştirme', 'Tişört giydiğinizde kollarınızın daha dolu görünmesini sağlayan kas grubu: Ön kollar.', '<p>Çoğu kişi biceps çalışır ama ön kolları unutur. Farmer Walk (Çiftçi Yürüyüşü) ve Reverse Curl hareketleriyle o \"Popeye\" görüntüsünü elde edebilirsiniz.</p>', '1', '2025-04-30 20:04:52', 573),
(42, 'CrossFit WOD: Evde Yüksek Nabız Antrenmanı', 'Zamanla yarışacağınız, yağ yakan ve kondisyon artıran 20 dakikalık ev antrenmanı.', '<p>AMRAP (As Many Rounds As Possible) mantığıyla 20 dakikada: 10 Burpee, 20 Squat, 30 Jumping Jack. Kaç tur yapabileceksiniz? Nabzınız hiç düşmeyecek.</p>', '1', '2025-10-01 20:04:52', 196),
(43, 'Kafein ve Performans: Antrenmandan Önce Kahve İçilmeli Mi?', 'En ucuz ve en etkili pre-workout: Kahve. Ne zaman ve ne kadar içmelisiniz?', '<p>Kafein, yorgunluk sinyallerini bloklayarak daha sert antrenman yapmanızı sağlar. İdeal zamanlama antrenmandan 30-45 dakika öncesidir. Ancak akşam antrenmanlarında uyku kalitesine dikkat edin.</p>', '2', '2025-07-11 20:04:52', 606),
(44, 'Testosteron Seviyesini Doğal Yollarla Artırmak', 'Erkeklik hormonu olarak bilinen testosteronu artırmanın bilimsel yolları.', '<p>Yeterli D vitamini, çinko alımı, ağır bacak antrenmanları ve kaliteli uyku... Testosteron seviyenizi maksimize etmek için bu 4 kurala hayatınızda yer açın.</p>', '2', '2025-05-22 20:04:52', 393),
(45, 'BCAA Gerekli Mi? Para Tuzağı Mı?', 'Supplement dünyasının en tartışmalı konusu. BCAA almaya gerçekten gerek var mı?', '<p>Eğer günlük protein ihtiyacınızı tavuk, et ve yumurtadan karşılıyorsanız, ekstra BCAA almak \"pahalı bir idrar\" üretmekten başka işe yaramayabilir. Ancak aç karnına kardiyo yaparken kas korumak için kullanılabilir.</p>', '2', '2025-06-16 20:04:52', 455),
(46, 'Ketojenik Diyet ve Sporcu Performansı', 'Karbonhidratı sıfırlayarak yağ yakmak mümkün mü? Performans düşer mi?', '<p>Vücudu yağ yakıt moduna (ketozis) sokmak yağ yakımını hızlandırır. Ancak patlayıcı güç gerektiren sporlarda (sprint, halter) karbonhidrat eksikliği performans düşüşüne neden olabilir.</p>', '2', '2025-05-02 20:04:52', 561),
(47, 'Kas Hafızası (Muscle Memory) Nedir?', 'Spora ara verince kaslar erir mi? Geri döndüğünüzde ne kadar sürede toparlarsınız?', '<p>Yıllarca spor yapıp bıraksanız bile, kas hücrelerindeki çekirdek sayısı (myonuclei) kaybolmaz. Geri döndüğünüzde, hiç yapmamış birine göre 3-4 kat daha hızlı eski formunuza kavuşursunuz.</p>', '2', '2025-09-04 20:04:52', 206),
(48, 'DOMS Ağrısı: Antrenman Sonrası Hamlık', 'Antrenmandan sonraki gün yürüyemiyor musunuz? Bu iyiye işaret mi?', '<p>DOMS (Gecikmiş Başlangıçlı Kas Ağrısı), kas liflerindeki mikro yırtıklardan kaynaklanır. Ancak ağrı olmaması gelişmediğiniz anlamına gelmez. Vücut zamanla adapte olur ve ağrılar azalır.</p>', '2', '2025-05-25 20:04:52', 310),
(49, 'Glutamin Ne İşe Yarar? Bağışıklık ve Toparlanma', 'Bağırsak sağlığı ve yoğun antrenman dönemlerinde bağışıklığı korumak için glutamin.', '<p>Glutamin, kas geliştirmekten ziyade vücut direncini artırmak için önemlidir. Çok sert diyet veya antrenman dönemlerinde hastalanmamak için supplement kürüne eklenebilir.</p>', '2', '2025-07-26 20:04:52', 73),
(50, 'Antrenmanda Müzik Dinlemenin Etkisi', 'Kulaklığınızı takın ve dünyayı sessize alın. Müzik doğal bir dopingdir.', '<p>Bilimsel araştırmalar, sevdiğiniz ve yüksek tempolu müzikleri dinlemenin antrenman performansını %15 oranında artırabildiğini gösteriyor. Ritmi yakalayın, ağırlığı kaldırın.</p>', '2', '2025-05-20 20:04:52', 612),
(51, 'Sporcu İçecekleri ve Elektrolit Dengesi', 'Sadece su içmek yeterli mi? Terle kaybettiğimiz mineralleri nasıl yerine koyarız?', '<p>1 saati aşan yoğun antrenmanlarda sadece su içmek yetmez; sodyum ve potasyum kaybı kramplara yol açar. Maden suyu veya izotonik içecekler bu dengeyi korumanıza yardımcı olur.</p>', '2', '2025-08-21 20:04:52', 426),
(52, 'Aç Karnına Kardiyo (Fasted Cardio) Efsanesi', 'Sabah aç karnına koşmak daha mı fazla yağ yakar?', '<p>Teorik olarak evet, yağ depolarını kullanırsınız. Ancak günün sonunda önemli olan toplam kalori açığıdır. Aç karnına bayılacak gibi oluyorsanız kendinizi zorlamayın, tok karnına da yağ yakılır.</p>', '2', '2025-07-21 20:04:52', 424);
